import{_ as t,a,o,a6 as d}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/dashboard/index.md","filePath":"api/graphql-api/admin/dashboard/index.md","lastUpdated":1787725411000}'),r={name:"api/graphql-api/admin/dashboard/index.md"};function s(n,e,i,h,c,l){return o(),a("div",null,e[0]||(e[0]=[d('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p>The Dashboard menu returns the aggregate figures that power the Bagisto admin <strong>Dashboard</strong> screen — sales, orders, customers, visitors, stock alerts, top products and top customers. It mirrors the admin <strong>Dashboard</strong> landing page.</p><h2 id="the-dashboard-is-seven-separate-queries" tabindex="-1">The dashboard is <strong>seven</strong> separate queries <a class="header-anchor" href="#the-dashboard-is-seven-separate-queries" aria-label="Permalink to &quot;The dashboard is **seven** separate queries&quot;">​</a></h2><p>This is the most important thing to understand about this menu.</p><p>The Dashboard you see in the panel is <strong>not one response</strong>. The page is assembled from <strong>seven independent queries</strong>, one per section, each selected with the <code>type</code> argument. A single query returns <strong>one section</strong> of the dashboard. To render the whole screen, run <code>statsAdminDashboard</code> once per <code>type</code> (or only for the sections you need).</p><p>The <code>statistics</code> payload <strong>changes shape per <code>type</code></strong> — sometimes an object, sometimes a flat array — so always branch on <code>type</code> when consuming it.</p><table tabindex="0"><thead><tr><th>Dashboard section (admin panel)</th><th><code>type</code></th><th><code>statistics</code> is</th></tr></thead><tbody><tr><td><strong>Overall Details</strong> cards</td><td><code>over-all</code> (default)</td><td>object</td></tr><tr><td><strong>Today&#39;s Details</strong> + today&#39;s order list</td><td><code>today</code></td><td>object</td></tr><tr><td><strong>Stock Threshold</strong> product list</td><td><code>stock-threshold-products</code></td><td>array</td></tr><tr><td><strong>Store Stats</strong> sales chart</td><td><code>total-sales</code></td><td>object (with <code>over_time</code> series)</td></tr><tr><td><strong>Visitors</strong> chart</td><td><code>total-visitors</code></td><td>object (with <code>over_time</code> series)</td></tr><tr><td><strong>Top Selling Products</strong> list</td><td><code>top-selling-products</code></td><td>array</td></tr><tr><td><strong>Customer With Most Sales</strong> list</td><td><code>top-customers</code></td><td>array</td></tr></tbody></table><h2 id="date-window" tabindex="-1">Date window <a class="header-anchor" href="#date-window" aria-label="Permalink to &quot;Date window&quot;">​</a></h2><p><code>start</code> / <code>end</code> (both <code>YYYY-MM-DD</code>) bound the figures and drive the <code>previous</code> baseline behind every <code>progress</code> percentage — the previous period is the same-length window immediately before <code>start</code>. <code>start</code> defaults to <strong>30 days ago</strong>, <code>end</code> to <strong>today</strong>. <code>channel</code> (a channel <strong>code</strong>) scopes the figures to a single storefront channel.</p><h3 id="daterange-is-null-over-graphql" tabindex="-1"><code>dateRange</code> is <code>null</code> over GraphQL <a class="header-anchor" href="#daterange-is-null-over-graphql" aria-label="Permalink to &quot;`dateRange` is `null` over GraphQL&quot;">​</a></h3><p>The camelCase <code>dateRange</code> field returns <strong><code>null</code></strong> over GraphQL in this build; <code>type</code> and <code>statistics</code> are fully populated. If you need the formatted label, read it from the <a href="/api/rest-api/admin/dashboard/stats.html">REST endpoint</a>, or reconstruct it from the <code>start</code> / <code>end</code> you sent.</p><h2 id="queries-in-this-menu" tabindex="-1">Queries in this menu <a class="header-anchor" href="#queries-in-this-menu" aria-label="Permalink to &quot;Queries in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Query</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/dashboard/stats.html">Dashboard statistics</a></td><td><code>statsAdminDashboard</code></td></tr></tbody></table><p>The Dashboard is read-only — there are no mutations on this menu. For deeper, dedicated sales / customer / product reports, see <a href="/api/graphql-api/admin/reporting/">Reporting</a>.</p><p>All Dashboard queries require only an admin Bearer token (no permission gate) — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',15)]))}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
